import{_ as a,c as r,o,a3 as e}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"自訂","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/customize.md","filePath":"zh-TW/guide/customize.md","lastUpdated":1786595765000}'),n={name:"zh-TW/guide/customize.md"};function i(l,t,s,d,g,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="自訂" tabindex="-1">自訂 <a class="header-anchor" href="#自訂" aria-label="Permalink to &quot;自訂&quot;">​</a></h1><p>讓 ClipboardxAI 依照你的方式運作。本指南涵蓋你可以調整的設定。</p><h2 id="一般-general" tabindex="-1">一般（General） <a class="header-anchor" href="#一般-general" aria-label="Permalink to &quot;一般（General）&quot;">​</a></h2><p>開啟 <strong>ClipboardxAI → Settings（設定）</strong>（或按下 <code>Cmd+,</code>）。</p><ul><li><strong>Language（語言）</strong>：English、简体中文、繁體中文、日本語。</li><li><strong>Launch at Login（登入時啟動）</strong>：在你登入時自動啟動應用程式。</li><li><strong>Appearance（外觀）</strong>：Light（淺色）、Dark（深色）或 System（跟隨 macOS）。</li></ul><h2 id="ai-設定-ai-configuration" tabindex="-1">AI 設定（AI Configuration） <a class="header-anchor" href="#ai-設定-ai-configuration" aria-label="Permalink to &quot;AI 設定（AI Configuration）&quot;">​</a></h2><p>在 <strong>Settings → AI（設定 → AI）</strong> 中設定雲端 AI：</p><table tabindex="0"><thead><tr><th>設定</th><th>選項</th><th>說明</th></tr></thead><tbody><tr><td><strong>Provider（供應商）</strong></td><td>DeepSeek、MiniMax、GLM、Kimi、Mistral、Ollama、OpenAI、Anthropic、Gemini</td><td>要呼叫的 OpenAI 相容服務</td></tr><tr><td><strong>API Key</strong></td><td>你的 key</td><td>儲存在 <strong>Keychain</strong> 中，絕不會以純文字寫入磁碟</td></tr><tr><td><strong>Model（模型）</strong></td><td>依供應商而定</td><td>用於 AI 動作的模型</td></tr><tr><td><strong>Cloud AI enabled（啟用雲端 AI）</strong></td><td>開／關</td><td>傳送剪貼內容至雲端的主開關</td></tr></tbody></table><p>雲端 AI <strong>預設為關閉</strong>。啟用後，你的剪貼內容只會傳送給你所設定的供應商。</p><h2 id="動作-actions" tabindex="-1">動作（Actions） <a class="header-anchor" href="#動作-actions" aria-label="Permalink to &quot;動作（Actions）&quot;">​</a></h2><p>自訂工具的行為：</p><ul><li><strong>Auto-run on output（輸出時自動執行）</strong>：開啟後，所選工具會在你複製的瞬間自動執行。</li><li><strong>Excluded apps（排除的應用程式）</strong>：此處列出的應用程式會被剪貼簿監控與自動執行跳過（例如密碼管理器）。</li><li><strong>Tool order（工具順序）</strong>：在 AI 工具視窗中，拖曳已安裝的工具來重新排序；你的順序會被記住。</li></ul><h2 id="隱私-privacy" tabindex="-1">隱私（Privacy） <a class="header-anchor" href="#隱私-privacy" aria-label="Permalink to &quot;隱私（Privacy）&quot;">​</a></h2><p>開啟 <strong>Settings → Privacy（設定 → 隱私）</strong>：</p><ul><li><strong>Cloud AI opt-in（雲端 AI 加入選項）</strong>：傳送資料給供應商的主開關。</li><li><strong>Excluded apps（排除的應用程式）</strong>：停止擷取特定的應用程式。</li><li><strong>History controls（歷史紀錄控制）</strong>：管理剪貼內容在你的裝置上保留多久。</li></ul><p>所有歷史紀錄都保留在本地。我們不會上傳剪貼內容或執行分析。</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>管理已安裝的動作：</p><ul><li><strong>Browse（瀏覽）</strong>：從 AI 工具視窗或網站開啟 <strong>Marketplace</strong>。</li><li><strong>Install（安裝）</strong>：點擊某個動作上的 <strong>Install（安裝）</strong>，透過深層連結將它加入。</li><li><strong>Remove（移除）</strong>：從你的<strong>已安裝</strong>清單解除安裝某個動作。</li></ul><h2 id="選單列-menu-bar" tabindex="-1">選單列（Menu Bar） <a class="header-anchor" href="#選單列-menu-bar" aria-label="Permalink to &quot;選單列（Menu Bar）&quot;">​</a></h2><ul><li><strong>Show in menu bar（顯示於選單列）</strong>：啟用／停用系統列圖示。</li><li><strong>Quit on close（關閉時退出）</strong>：選擇應用程式是否在背景持續執行。</li></ul><h2 id="小訣竊" tabindex="-1">小訣竊 <a class="header-anchor" href="#小訣竊" aria-label="Permalink to &quot;小訣竊&quot;">​</a></h2><ul><li>在需要之前保持雲端 AI 關閉——本地工具已涵蓋大多數日常清理需求。</li><li>將密碼管理器與安全輸入的應用程式加入 <strong>Excluded apps（排除的應用程式）</strong>，讓機密資訊永不被擷取。</li><li>將自動執行與本地工具搭配使用，讓每次複製都自動完成免動手文字清理。</li></ul>',23)])])}const p=a(n,[["render",i]]);export{h as __pageData,p as default};
